-- FIFA 211 member master and alias normalization
ALTER TABLE teams ADD COLUMN is_fifa_member INTEGER NOT NULL DEFAULT 0;
ALTER TABLE teams ADD COLUMN active INTEGER NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS fifa_members(
 fifa_code TEXT PRIMARY KEY,
 official_name TEXT NOT NULL,
 confederation TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1,
 source_url TEXT NOT NULL DEFAULT 'https://inside.fifa.com/en/about-fifa/associations',
 updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS fifa_aliases(
 alias TEXT PRIMARY KEY,
 fifa_code TEXT NOT NULL,
 source TEXT NOT NULL DEFAULT 'curated',
 FOREIGN KEY(fifa_code) REFERENCES fifa_members(fifa_code)
);
CREATE TABLE IF NOT EXISTS unmapped_team_names(
 normalized_name TEXT PRIMARY KEY,
 original_name TEXT NOT NULL,
 source TEXT,
 occurrence_count INTEGER NOT NULL DEFAULT 1,
 first_seen TEXT DEFAULT CURRENT_TIMESTAMP,
 last_seen TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_teams_fifa_member ON teams(is_fifa_member,active);
CREATE INDEX IF NOT EXISTS idx_fifa_alias_code ON fifa_aliases(fifa_code);
